function createBaseServerMsg(): ServerMsg {
  return { kind: undefined };
}

export const ServerMsg: MessageFns<ServerMsg> = {
  encode(message: ServerMsg, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    switch (message.kind?.$case) {
      case "result":
        CommandResult.encode(message.kind.result, writer.uint32(10).fork()).join();
        break;
      case "upsert":
        EntityUpsert.encode(message.kind.upsert, writer.uint32(18).fork()).join();
        break;
      case "remove":
        EntityRemove.encode(message.kind.remove, writer.uint32(26).fork()).join();
        break;
      case "move":
        MoveSegment.encode(message.kind.move, writer.uint32(34).fork()).join();
        break;
      case "era":
        EraChanged.encode(message.kind.era, writer.uint32(66).fork()).join();
        break;
      case "snapshot":
        ViewportSnapshot.encode(message.kind.snapshot, writer.uint32(74).fork()).join();
        break;
      case "world":
        WorldSnapshot.encode(message.kind.world, writer.uint32(82).fork()).join();
        break;
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): ServerMsg {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    let end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseServerMsg();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.kind = { $case: "result", result: CommandResult.decode(reader, reader.uint32()) };
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.kind = { $case: "upsert", upsert: EntityUpsert.decode(reader, reader.uint32()) };
          continue;
        }
        case 3: {
          if (tag !== 26) {
            break;
          }

          message.kind = { $case: "remove", remove: EntityRemove.decode(reader, reader.uint32()) };
          continue;
        }
        case 4: {
          if (tag !== 34) {
            break;
          }

          message.kind = { $case: "move", move: MoveSegment.decode(reader, reader.uint32()) };
          continue;
        }
        case 8: {
          if (tag !== 66) {
            break;
          }

          message.kind = { $case: "era", era: EraChanged.decode(reader, reader.uint32()) };
          continue;
        }
        case 9: {
          if (tag !== 74) {
            break;
          }

          message.kind = { $case: "snapshot", snapshot: ViewportSnapshot.decode(reader, reader.uint32()) };
          continue;
        }
        case 10: {
          if (tag !== 82) {
            break;
          }

          message.kind = { $case: "world", world: WorldSnapshot.decode(reader, reader.uint32()) };
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  create<I extends Exact<DeepPartial<ServerMsg>, I>>(base?: I): ServerMsg {
    return ServerMsg.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<ServerMsg>, I>>(object: I): ServerMsg {
    const message = createBaseServerMsg();
    switch (object.kind?.$case) {
      case "result": {
        if (object.kind?.result !== undefined && object.kind?.result !== null) {
          message.kind = { $case: "result", result: CommandResult.fromPartial(object.kind.result) };
        }
        break;
      }
      case "upsert": {
        if (object.kind?.upsert !== undefined && object.kind?.upsert !== null) {
          message.kind = { $case: "upsert", upsert: EntityUpsert.fromPartial(object.kind.upsert) };
        }
        break;
      }
      case "remove": {
        if (object.kind?.remove !== undefined && object.kind?.remove !== null) {
          message.kind = { $case: "remove", remove: EntityRemove.fromPartial(object.kind.remove) };
        }
        break;
      }
      case "move": {
        if (object.kind?.move !== undefined && object.kind?.move !== null) {
          message.kind = { $case: "move", move: MoveSegment.fromPartial(object.kind.move) };
        }
        break;
      }
      case "era": {
        if (object.kind?.era !== undefined && object.kind?.era !== null) {
          message.kind = { $case: "era", era: EraChanged.fromPartial(object.kind.era) };
        }
        break;
      }
      case "snapshot": {
        if (object.kind?.snapshot !== undefined && object.kind?.snapshot !== null) {
          message.kind = { $case: "snapshot", snapshot: ViewportSnapshot.fromPartial(object.kind.snapshot) };
        }
        break;
      }
      case "world": {
        if (object.kind?.world !== undefined && object.kind?.world !== null) {
          message.kind = { $case: "world", world: WorldSnapshot.fromPartial(object.kind.world) };
        }
        break;
      }
    }
    return message;
  },
};

type Builtin = Date | Function | Uint8Array | string | number | boolean | bigint | undefined;

export type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends { $case: string } ? { [K in keyof Omit<T, "$case">]?: DeepPartial<T[K]> } & { $case: T["$case"] }
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
